/**
 * Dashboard controller
 *
 * Handles header button interaction and delegates
 * state persistence + block replay to dedicated modules.
 */
define([
    'local_chartplugin/state_manager',
    'local_chartplugin/block_replay'
], function(StateManager, BlockReplay) {

    /**
     * Initialise analytics dashboard.
     */
    function init() {
        const buttons = document.querySelectorAll('#header-buttons .button');

        buttons.forEach(button => {
            button.addEventListener('click', () => {
                buttons.forEach(b => b.classList.remove('active'));
                button.classList.add('active');

                const chartKey = button.dataset.chart;
                const title = button.innerText.trim();

                StateManager.record(chartKey, title);
                BlockReplay.render();
            });
        });

        // Populate blocks on page load
        BlockReplay.render();
    }

    return { init };
});
